import os, re

# Load all grids from this session (demo pairs and test input)
def load_grids():
    session_dir = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not session_dir:
        print("No session directory found")
        return {}

    sessions_file = os.path.join(session_dir, '..', 'sessions', os.path.basename(session_dir) + '.jsonl')
    try:
        content = open(sessions_file).read()
    except:
        print(f"Could not find sessions file: {sessions_file}")
        return {}

    G = {}
    pattern = re.compile(r'(Demo pair \d+ (?:input|output)|(?:Test input) \((\d+)x(\d+)\)):\n', re.MULTILINE)

    lines = content.strip().split('\n')
    i = 0
    for label in lines:
        if label.startswith('Demo pair') or label.startswith('Test input'):
            match = re.match(r'Demo pair (\d+) (input|output)', label)
            if match:
                pair_num = match.group(1)
                grid_type = match.group(2)
                key = f"pair{pair_num}-{grid_type}"
            else:
                match = re.match(r'Test input \((\d+)x(\d+)\)', label)
                if match:
                    key = 'Test input'
                    grid_type = None
                else:
                    continue

            if key in G:
                print(f"Warning: {key} already exists, skipping")
                i += len(label.split('\n'))
                continue

            # Get dimensions from key
            rows, cols = 0, 0
            if key == 'Test input':
                match = re.match(r'Test input \((\d+)x(\d+)\)', label)
                if match:
                    rows, cols = int(match.group(1)), int(match.group(2))
            else:
                match = re.match(r'Demo pair (\d+) (input|output)', label)
                if match:
                    rows, cols = int(match.group(2)), int(match.group(3))  # This won't work for input/output, skip
                continue

            # Parse the grid
            grid_rows = []
            j = i + label.split('\n')
            for j in range(len(label.split('\n'))[:int(rows)]):
                row_text = label.split('\n')[j].strip()
                if row_text.isdigit() and row_text:
                    grid_rows.append([int(x) for x in row_text.split()])

            G[key] = grid_rows
            i += len(label.split('\n'))

    print("Loaded grids:", sorted(G.keys()))
    for k, v in sorted(G.items()):
        print(f"  {k}: {len(v)}x{len(v[0]) if v else 0}")
    return G

G = load_grids()

