import json

# New theory: after barrier, row 8 should copy row 7's pattern (the barrier)
# This interprets barrier as "repeat this pattern"

def try_copy_barrier_pattern(grid):
    rows = len(grid)
    cols = len(grid[0])
    results = [[0]*cols for _ in range(rows)]
    expansion_used = False

    for r in range(rows):
        row = grid[r]
        is_barrier = all(c == 2 for c in row)
        has_nonzero = any(c != 0 for c in row)
        is_uniform = has_nonzero and all(c == row[0] for c in row if c != 0)

        if is_barrier:
            results[r] = row[:]
        elif has_nonzero and is_uniform and not expansion_used:
            val = row[0]
            new_val = val * 2
            results[r] = [min(new_val, 9)] * cols
            expansion_used = True
        elif has_nonzero:
            if r > 0:
                prev_row_input = grid[r-1]
                results[r] = [prev_row_input[c] for c in range(cols)]
            else:
                results[r] = [0] * cols
        else:
            if r > 0:
                prev_row_input = grid[r-1]
                results[r] = [prev_row_input[c] for c in range(cols)]
            else:
                results[r] = [0] * cols

    # After barrier, special handling: copy barrier pattern
    barrier_r = -1
    for r in range(rows):
        if all(c == 2 for c in grid[r]):
            barrier_r = r
            break
    if barrier_r >= 0 and barrier_r < rows - 1:
        # Rows after barrier copy barrier
        for r in range(barrier_r + 1, rows):
            if not grid[r]:  # empty row already doesn't match
                results[r] = grid[barrier_r][:]

    return results

